WITH state_returns AS ( SELECT w.w_state, SUM(wr.wr_return_amt_inc_tax) AS total_return_amount_inc_tax, AVG(wr.wr_return_quantity) AS avg_return_quantity, COUNT(DISTINCT i.i_item_sk) AS distinct_items_returned FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN inventory inv ON i.i_item_sk = inv.inv_item_sk JOIN warehouse w ON inv.inv_warehouse_sk = w.w_warehouse_sk GROUP BY w.w_state ) SELECT sr.w_state, CASE WHEN sr.w_state IN ('NY','NJ','CT','MA','PA','VA','MD','DC') THEN 'East' WHEN sr.w_state IN ('CA','OR','WA','NV','AZ') THEN 'West' WHEN sr.w_state IN ('TX','OK','NM','CO') THEN 'Central' ELSE 'Other' END AS region, sr.total_return_amount_inc_tax, sr.avg_return_quantity, sr.distinct_items_returned, SUM(sr.total_return_amount_inc_tax) OVER (ORDER BY sr.w_state ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amount FROM state_returns sr ORDER BY sr.w_state
